-- Utah. The state had eight stops, mostly gravity hills from the scan.
--
-- The cleanest batch of the project: 116 parsed, none missing a source, no
-- duplicates within the batch, and only six categories the map had not seen.
-- blm.gov and nps.gov are the top two domains.
--
-- One rename. Balanced Rock is the fourth in the index, after Baraboo, Big
-- Bend and Idaho — this is the famous one in Arches and it still does not get
-- the plain slug, because the first to arrive kept it and renaming a live page
-- to make room would break every link to it.
--
-- The whole state is Mountain time, no exceptions.
--
-- Worth noting what this fills in. Utah had eight stops and now has the Spiral
-- Jetty, the Sun Tunnels, Skinwalker Ranch's public viewpoint, the Summum
-- pyramid, Topaz, Mountain Meadows, and about a dozen rock art panels that are
-- among the oldest things in this index by several thousand years.
--
-- 116 stops, every one with a source.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, website, timezone, verified_at)
values
  ('Bear Lake Monster — Bear Lake State Park Marina', 'bear-lake-monster-bear-lake-state-park-marina', 'cryptids', 41.94446, -111.39949, 'Garden City', 'UT', 'Bear Lake has carried stories of a long, serpentine lake creature since the nineteenth century. The marina gives OddWay travelers a lawful public stop on the lake itself while the monster remains folklore rather than a claimed fact.', 'open', 'https://www.visitutah.com/articles/bear-lake-monster-winterfest', null, 'America/Denver', now()),
  ('Historic 25th Street — Two Bit Street', 'historic-25th-street-two-bit-street', 'haunted', 41.22088, -111.97337, 'Ogden', 'UT', 'Ogden''s old railroad-era vice district accumulated stories of underground tunnels, killings, gambling and reported apparitions. The street is fully public and remains the core of the city''s official Paranormal Ogden route.', 'open', 'https://www.visitogden.com/things-to-do/self-guided-tours/paranormal-ogden/', null, 'America/Denver', now()),
  ('Ogden Union Station', 'ogden-union-station', 'haunted', 41.22076, -111.97924, 'Ogden', 'UT', 'The historic railroad station is associated with several local ghost stories, including reports of children, footsteps and a woman seen on the upper floor. It now functions as a museum complex, so paranormal claims should be treated strictly as lore.', 'limited', 'https://www.visitogden.com/blog/haunted-places-and-history/', null, 'America/Denver', now()),
  ('Peery''s Egyptian Theater', 'peerys-egyptian-theater', 'haunted', 41.22368, -111.97033, 'Ogden', 'UT', 'This restored 1924 Egyptian Revival movie palace is one of Ogden''s official paranormal-history stops and has stories involving unexplained music, voices and a young girl''s apparition. Interior access depends on performances, tours and events.', 'limited', 'https://www.visitogden.com/directory/peerys-egyptian-theater/', null, 'America/Denver', now()),
  ('Ogden City Cemetery — WWI Soldier Statue', 'ogden-city-cemetery-wwi-soldier-statue', 'folklore', 41.22902, -111.9475, 'Ogden', 'UT', 'Local legend says the World War I soldier statue in Ogden City Cemetery can appear to move or follow visitors with its eyes. The story is part of the city''s official paranormal tour; visit only during lawful cemetery hours and treat the grounds respectfully.', 'limited', 'https://www.visitogden.com/blog/haunted-places-and-history/', null, 'America/Denver', now()),
  ('Lilly E. Gray — ''Victim of the Beast 666'' Grave', 'lilly-e-gray-victim-of-the-beast-666-grave', 'weird-history', 40.78367, -111.8623, 'Salt Lake City', 'UT', 'Lilly Gray''s headstone bears the unexplained inscription ''Victim of the Beast 666,'' making it one of Utah''s best-known cemetery curiosities. State archivists have documented the woman behind the legend and caution against supernatural assumptions.', 'limited', 'https://archives.utah.gov/2017/10/31/lilly-e-gray/', null, 'America/Denver', now()),
  ('Jacob Moritz ''Emo'' Grave', 'jacob-moritz-emo-grave', 'folklore', 40.77755, -111.85878, 'Salt Lake City', 'UT', 'Brewer and politician Jacob Moritz became the subject of a long-running Salt Lake Cemetery ghost tale under the nickname ''Emo.'' The city itself identifies him as a cemetery figure associated with legendary ghost lore.', 'limited', 'https://www.slc.gov/cemetery/history-of-the-salt-lake-city-cemetery/', null, 'America/Denver', now()),
  ('Summum Pyramid', 'summum-pyramid', 'roadside-oddities', 40.76654, -111.90994, 'Salt Lake City', 'UT', 'A modern pyramid beside the freeway belongs to Summum, a small religious organization known for its teachings about mummification and its modern mummification practices. The exterior is easily seen, but interior access is controlled by the organization.', 'limited', 'https://www.summum.us/', null, 'America/Denver', now()),
  ('Saltair', 'saltair', 'haunted', 40.74614, -112.18898, 'Magna', 'UT', 'The present Saltair stands near the remains of earlier Great Salt Lake resorts destroyed by fire, water and abandonment. Its repeated cycles of destruction helped inspire a reputation for being cursed, while the surviving building operates as an event venue.', 'limited', 'https://www.roadsideamerica.com/tip/2740', null, 'America/Denver', now()),
  ('Skinwalker Ranch — Public-Road Viewpoint', 'skinwalker-ranch-public-road-viewpoint', 'ufos', 40.25841, -109.88895, 'Ballard', 'UT', 'The private ranch is internationally associated with reports of UFOs, strange lights, livestock injuries and other paranormal claims. OddWay should never route visitors onto the ranch; this entry is a lawful public-road lore stop only.', 'roadside', 'https://skinwalker-ranch.com/', null, 'America/Denver', now()),
  ('Nine Mile Canyon', 'nine-mile-canyon', 'weird-history', 39.55555, -110.6678, 'Wellington', 'UT', 'Often called the world''s longest art gallery, this long canyon contains thousands of Fremont and Ute petroglyphs, pictographs, inscriptions and historic homestead remains. Visitors must respect private parcels mixed among public land.', 'open', 'https://www.blm.gov/visit/9-mile-canyon', null, 'America/Denver', now()),
  ('Daddy Canyon Rock Art Trail', 'daddy-canyon-rock-art-trail', 'weird-history', 39.78546, -110.16669, 'Wellington', 'UT', 'A signed trail from a developed Nine Mile Canyon trailhead passes numerous Fremont rock-art panels along the canyon walls. The BLM provides parking, shade and restrooms at the route point.', 'open', 'https://www.blm.gov/visit/daddy-canyon-trailhead', null, 'America/Denver', now()),
  ('Sego Canyon Rock Art', 'sego-canyon-rock-art', 'weird-history', 39.01811, -109.71036, 'Thompson Springs', 'UT', 'Three distinct rock-art traditions appear together here: Barrier Canyon, Fremont and Ute. The large ghostlike Barrier Canyon figures make this one of Utah''s strongest OddWay archaeology stops.', 'open', 'https://www.blm.gov/visit/sego-canyon-rock-art-interpretive-site', null, 'America/Denver', now()),
  ('Buckhorn Wash Pictograph Panel', 'buckhorn-wash-pictograph-panel', 'weird-history', 39.12359, -110.69378, 'Castle Dale', 'UT', 'Large red Barrier Canyon-style figures watch over Buckhorn Wash beside later Fremont petroglyphs and historic CCC inscriptions. The panel is publicly managed with parking, interpretation and a short trail.', 'open', 'https://www.blm.gov/visit/buckhorn-panel', null, 'America/Denver', now()),
  ('Black Dragon Pictograph Panel', 'black-dragon-pictograph-panel', 'weird-history', 38.94305, -110.42495, 'Green River', 'UT', 'Chalking by an earlier visitor merged several ancient figures into what looked like a winged dragon, giving the wash its modern name. The original art is protected and reached on a rough high-clearance route.', 'limited', 'https://www.blm.gov/visit/black-dragon-pictograph-panel', null, 'America/Denver', now()),
  ('Rochester Panel', 'rochester-panel', 'weird-history', 38.90676, -111.19511, 'Emery', 'UT', 'This dense cliff panel mixes human figures, animals and abstract imagery so unusual that specialists still debate whether its dominant style is Fremont or older Barrier Canyon. A short public hike reaches the overlook.', 'open', 'https://www.blm.gov/visit/rochester-panel', null, 'America/Denver', now()),
  ('Head of Sinbad Pictographs', 'head-of-sinbad-pictographs', 'weird-history', 38.88089, -110.77083, 'Emery', 'UT', 'Remote pictographs include an eerie humanlike figure crowned by a snake near Locomotive Point. The BLM warns that access requires high-clearance four-wheel drive and desert travel preparation.', 'limited', 'https://www.blm.gov/visit/head-sinbad', null, 'America/Denver', now()),
  ('Newspaper Rock State Historical Monument', 'newspaper-rock-state-historical-monument', 'weird-history', 37.98842, -109.51827, 'Monticello', 'UT', 'A dark sandstone panel beside Highway 211 holds hundreds of petroglyphs accumulated over centuries. The developed BLM site has paved parking and a short accessible approach.', 'open', 'https://www.blm.gov/visit/newspaper-rock', null, 'America/Denver', now()),
  ('Parowan Gap Petroglyphs', 'parowan-gap-petroglyphs', 'weird-history', 37.90905, -112.98358, 'Parowan', 'UT', 'More than 1,500 carvings cover the cliffs of this dramatic natural gap, with many attributed to Fremont people and some possibly much older. The site remains culturally significant to living Native communities.', 'open', 'https://www.nps.gov/articles/visit-indigenous-landscapes.htm', null, 'America/Denver', now()),
  ('Capitol Reef Fremont Petroglyph Panel', 'capitol-reef-fremont-petroglyph-panel', 'weird-history', 38.28864, -111.24759, 'Torrey', 'UT', 'Boardwalks along State Route 24 lead directly to Fremont petroglyphs depicting bighorn sheep and distinctive human figures. It is one of the state''s easiest major rock-art stops to visit lawfully.', 'open', 'https://www.nps.gov/places/petroglyph-panel.htm', null, 'America/Denver', now()),
  ('Swelter Shelter Petroglyphs', 'swelter-shelter-petroglyphs', 'weird-history', 40.44199, -109.30304, 'Jensen', 'UT', 'One of Dinosaur National Monument''s easiest rock-art stops combines Fremont petroglyphs and pictographs only a short walk from the road. Federal protection rules prohibit touching, tracing or rubbing the images.', 'open', 'https://www.nps.gov/dino/learn/historyculture/viewing-petroglyphs-and-pictographs.htm', null, 'America/Denver', now()),
  ('Cub Creek Lizard Petroglyphs', 'cub-creek-lizard-petroglyphs', 'weird-history', 40.42491, -109.24032, 'Jensen', 'UT', 'Large lizard figures distinguish the Cub Creek panels from many other Fremont sites in the region. Two designated roadside stops provide legitimate access without wandering into unmarked archaeological areas.', 'open', 'https://www.nps.gov/dino/learn/historyculture/viewing-petroglyphs-and-pictographs.htm', null, 'America/Denver', now()),
  ('McConkie Ranch Petroglyphs', 'mcconkie-ranch-petroglyphs', 'weird-history', 40.58908, -109.47178, 'Vernal', 'UT', 'Private land opened to respectful visitors contains one of northeastern Utah''s most extraordinary concentrations of Fremont rock art, including elaborate horned and necklace-wearing human figures. Follow current ranch rules and donation guidance.', 'limited', 'https://www.visitutah.com/articles/unknown-otherworldly-near-vernal', null, 'America/Denver', now()),
  ('Bloomington Petroglyph Park', 'bloomington-petroglyph-park', 'weird-history', 37.05345, -113.61876, 'St. George', 'UT', 'A small city-managed neighborhood park preserves petroglyph-covered boulders in place instead of moving them into a museum. It gives travelers a quick, lawful archaeology stop within St. George.', 'open', 'https://www.sgcityutah.gov/', null, 'America/Denver', now()),
  ('Fremont Indian State Park Rock Art', 'fremont-indian-state-park-rock-art', 'weird-history', 38.57761, -112.33495, 'Sevier', 'UT', 'Trails around the park preserve petroglyphs and pictographs associated with a major Fremont village uncovered during Interstate 70 construction. Outdoor areas remain open while museum renovations are completed.', 'open', 'https://stateparks.utah.gov/parks/fremont-indian/', null, 'America/Denver', now()),
  ('Edge of the Cedars Pueblo', 'edge-of-the-cedars-pueblo', 'weird-history', 37.63299, -109.47704, 'Blanding', 'UT', 'An authentic Ancestral Puebloan village sits directly behind the museum, including a kiva visitors can enter by ladder. The site is interpreted as a living cultural landscape rather than an abandoned ruin playground.', 'open', 'https://stateparks.utah.gov/parks/edge-of-the-cedars/discover/', null, 'America/Denver', now()),
  ('Butler Wash Ruins Overlook', 'butler-wash-ruins-overlook', 'weird-history', 37.47643, -109.63282, 'Blanding', 'UT', 'A short public trail overlooks a large alcove containing Ancestral Puebloan rooms, granaries and a kiva. The overlook preserves distance from fragile structures while still giving a clear view.', 'open', 'https://www.blm.gov/visit/butler-wash-ruins', null, 'America/Denver', now()),
  ('House on Fire Ruin', 'house-on-fire-ruin', 'weird-history', 37.54379, -109.73952, 'Blanding', 'UT', 'Morning light makes the streaked sandstone roof above these ancestral structures appear to blaze like flames. The site is reached by a backcountry hike in Mule Canyon and must be visited without entering or touching the masonry.', 'limited', 'https://www.blm.gov/visit/kane-gulch-ranger-station', null, 'America/Denver', now()),
  ('Kane Gulch Ranger Station', 'kane-gulch-ranger-station', 'weird-history', 37.52445, -109.89578, 'Blanding', 'UT', 'The ranger station is the main public gateway for Grand Gulch archaeology and displays photographs, maps and information about protected rock art and ancestral sites. It is also the permit hub for deeper canyon travel.', 'limited', 'https://www.blm.gov/visit/kane-gulch-ranger-station', null, 'America/Denver', now()),
  ('Sand Island Petroglyph Panel', 'sand-island-petroglyph-panel', 'weird-history', 37.26984, -109.61512, 'Bluff', 'UT', 'A long cliff face above the San Juan River contains hundreds of petroglyphs spanning multiple eras. A developed BLM recreation area provides lawful access to the panel.', 'open', 'https://www.blm.gov/visit/sand-island-campground', null, 'America/Denver', now()),
  ('Hovenweep Square Tower Group', 'hovenweep-square-tower-group', 'weird-history', 37.38515, -109.07146, 'Montezuma Creek', 'UT', 'Multi-story ancestral stone towers stand along the rim and floor of Little Ruin Canyon, some built directly on boulders. The Square Tower Group is the monument''s primary developed archaeological trail.', 'open', 'https://www.nps.gov/hove/', null, 'America/Denver', now()),
  ('Natural Bridges — Horsecollar Ruin Overlook', 'natural-bridges-horsecollar-ruin-overlook', 'weird-history', 37.59707, -110.01393, 'Lake Powell', 'UT', 'A trail and overlook reveal a remarkably preserved ancestral site including structures whose doorways resemble horse collars. Visitors should remain on designated routes and never enter ruins.', 'open', 'https://www.nps.gov/nabr/', null, 'America/Denver', now()),
  ('Anasazi State Park Museum Village', 'anasazi-state-park-museum-village', 'weird-history', 37.91084, -111.42362, 'Boulder', 'UT', 'The museum stands beside remains of one of the largest known ancestral villages west of the Colorado River, with reconstructed and excavated structures on site. It combines archaeology with carefully interpreted public access.', 'open', 'https://stateparks.utah.gov/parks/anasazi/', null, 'America/Denver', now()),
  ('Frisco Ghost Town & Beehive Kilns', 'frisco-ghost-town-beehive-kilns', 'weird-history', 38.4603, -113.25983, 'Milford', 'UT', 'Frisco boomed around the Horn Silver Mine before collapse and decline left stone ruins and a row of massive beehive charcoal kilns beside State Route 21. Mine shafts and unstable ruins make exterior viewing the appropriate approach.', 'roadside', 'https://www.roadsideamerica.com/tip/49016', null, 'America/Denver', now()),
  ('Grafton Ghost Town', 'grafton-ghost-town', 'weird-history', 37.16777, -113.08198, 'Rockville', 'UT', 'Preserved pioneer buildings and a cemetery survive near Zion in one of Utah''s most photogenic abandoned settlements. A preservation organization manages the site, so visitors should stay on designated public areas.', 'limited', 'https://graftonheritage.org/', null, 'America/Denver', now()),
  ('Cisco Ghost Town', 'cisco-ghost-town', 'weird-history', 38.96916, -109.31958, 'Cisco', 'UT', 'This former railroad and oil stop with weathered buildings became a symbol of desert abandonment and later an artist-residency site. Much of the land is private, so OddWay should keep visitors on public roads.', 'roadside', 'https://www.visitutah.com/plan-your-trip/recommended-itineraries/thelma-louise-road-trip', null, 'America/Denver', now()),
  ('Sego Ghost Town', 'sego-ghost-town', 'weird-history', 39.02767, -109.7032, 'Thompson Springs', 'UT', 'Coal-mining ruins, foundations and a surviving company-store shell remain farther up the canyon from the Sego rock-art panels. The site is a legitimate historic stop, but visitors should avoid unstable structures.', 'open', 'https://www.blm.gov/visit/sego-canyon-rock-art-interpretive-site', null, 'America/Denver', now()),
  ('Old Iron Town', 'old-iron-town', 'weird-history', 37.60062, -113.45596, 'Cedar City', 'UT', 'Ruins of a nineteenth-century ironworks include a preserved beehive-shaped charcoal oven, furnace remnants and building foundations. Utah State Parks maintains the public site and interpretive trail.', 'open', 'https://stateparks.utah.gov/activities/museums/parks-areas/', null, 'America/Denver', now()),
  ('Silver Reef Ghost Town & Museum', 'silver-reef-ghost-town-museum', 'weird-history', 37.25367, -113.36722, 'Leeds', 'UT', 'Silver Reef was a rare mining town built around silver extracted from sandstone. The restored Wells Fargo building and surrounding ruins now form a museum complex focused on the boomtown''s unusual geology and history.', 'limited', 'https://silverreef.org/', null, 'America/Denver', now()),
  ('Topaz Incarceration Camp Historic Site', 'topaz-incarceration-camp-historic-site', 'weird-history', 39.41786, -112.77387, 'Delta', 'UT', 'Foundations, roads, landscaping traces and original fence remain where thousands of Japanese Americans were incarcerated during World War II. The Topaz Museum asks visitors to learn at the museum first and never remove artifacts.', 'limited', 'https://topazmuseum.org/museum/visit-historic-site/', null, 'America/Denver', now()),
  ('Topaz Museum', 'topaz-museum', 'weird-history', 39.35259, -112.57774, 'Delta', 'UT', 'This museum preserves artifacts, photographs and personal stories from the nearby wartime incarceration camp. It is the recommended starting point before visiting the fragile historic site outside town.', 'limited', 'https://topazmuseum.org/', null, 'America/Denver', now()),
  ('Mountain Meadows Massacre Memorial', 'mountain-meadows-massacre-memorial', 'weird-history', 37.47974, -113.63978, 'Veyo', 'UT', 'Memorials mark the landscape where more than 100 emigrants in the Baker-Fancher wagon train were killed in 1857. The site is solemn and should be treated as a memorial rather than a paranormal attraction.', 'open', 'https://www.nps.gov/places/mountain-meadows-massacre-site.htm', null, 'America/Denver', now()),
  ('German POW Massacre Memorial', 'german-pow-massacre-memorial', 'weird-history', 38.95646, -111.85708, 'Salina', 'UT', 'A memorial at the former Salina POW camp commemorates German prisoners killed in 1945 when an American guard fired into their tents. It preserves one of Utah''s least-known World War II tragedies.', 'open', 'https://historytogo.utah.gov/salina-pow-camp/', null, 'America/Denver', now()),
  ('Castle Gate Mine Disaster Memorial', 'castle-gate-mine-disaster-memorial', 'weird-history', 39.73557, -110.87264, 'Helper', 'UT', 'Memorial markers recall the 1924 Castle Gate Mine explosion that killed 172 miners. The disaster remains one of the deadliest industrial accidents in Utah history.', 'open', 'https://utahrails.net/coal/castle-gate-disaster.php', null, 'America/Denver', now()),
  ('Camp Floyd State Park Museum', 'camp-floyd-state-park-museum', 'weird-history', 40.25134, -112.09469, 'Fairfield', 'UT', 'Camp Floyd once housed thousands of U.S. troops sent to Utah during the 1857-58 Utah War. The surviving commissary, cemetery, Stagecoach Inn and schoolhouse form an unusually intact territorial-history cluster.', 'limited', 'https://stateparks.utah.gov/parks/camp-floyd/', null, 'America/Denver', now()),
  ('Fort Douglas Military Museum', 'fort-douglas-military-museum', 'weird-history', 40.76416, -111.83485, 'Salt Lake City', 'UT', 'The museum interprets the U.S. Army post established during the Civil War to watch over transportation routes and a region in political tension with the federal government. Historic weapons, vehicles and buildings remain on site.', 'limited', 'https://fortdouglas.org/', null, 'America/Denver', now()),
  ('Fort Buenaventura', 'fort-buenaventura', 'weird-history', 41.21649, -112.00241, 'Ogden', 'UT', 'A reconstructed fort marks the site of Miles Goodyear''s 1840s trading post, the first permanent non-Indigenous settlement in the region. Its stockade and cabins create a compact piece of frontier history beside modern Ogden.', 'open', 'https://www.visitogden.com/directory/fort-buenaventura/', null, 'America/Denver', now()),
  ('Bluff Fort Historic Site', 'bluff-fort-historic-site', 'weird-history', 37.28376, -109.55151, 'Bluff', 'UT', 'Reconstructed cabins, wagons and exhibits preserve the story of Mormon pioneers who reached Bluff after the grueling Hole-in-the-Rock expedition. The fort provides context for one of Utah''s strangest overland routes.', 'open', 'https://www.bluffutah.org/bluff-fort/', null, 'America/Denver', now()),
  ('Hole-in-the-Rock Pioneer Trail Terminus', 'hole-in-the-rock-pioneer-trail-terminus', 'weird-history', 37.25105, -110.48343, 'Lake Powell', 'UT', 'Pioneers in 1879-80 cut and blasted a wagon passage through this narrow cleft above the Colorado River. Reaching the end of the modern road requires a long rough drive, but the route is one of Utah''s most improbable pioneer-engineering stories.', 'limited', 'https://www.blm.gov/visit/hole-rock-road', null, 'America/Denver', now()),
  ('Territorial Statehouse State Park Museum', 'territorial-statehouse-state-park-museum', 'weird-history', 38.96783, -112.32528, 'Fillmore', 'UT', 'Utah''s first territorial capitol was designed as one wing of a much larger building that was never completed. The surviving stone structure now serves as a museum about the territory and the abandoned capital plan.', 'limited', 'https://stateparks.utah.gov/parks/territorial-statehouse/', null, 'America/Denver', now()),
  ('Cove Fort', 'cove-fort', 'weird-history', 38.60454, -112.58146, 'Cove Fort', 'UT', 'This volcanic-rock fort was built in 1867 along the Mormon Corridor to shelter travelers and support communications. The restored compound preserves rooms, wagons and defensive architecture.', 'limited', 'https://www.churchofjesuschrist.org/learn/historic-sites/utah/cove-fort', null, 'America/Denver', now()),
  ('Golden Spike — Last Spike Site', 'golden-spike-last-spike-site', 'weird-history', 41.6179, -112.55064, 'Promontory', 'UT', 'The first transcontinental railroad was ceremonially completed here in 1869. Replica steam locomotives, the original grade and the last-spike site turn a famous history-book event into a concrete OddWay route stop.', 'limited', 'https://www.nps.gov/gosp/index.htm', null, 'America/Denver', now()),
  ('Golden Spike — Big Fill / Big Trestle Grade', 'golden-spike-big-fill-big-trestle-grade', 'weird-history', 41.62913, -112.51591, 'Promontory', 'UT', 'Competing railroad crews built an enormous earth fill and timber trestle almost side by side while racing toward completion. The preserved grade can be explored on the park''s backcountry route.', 'open', 'https://www.nps.gov/gosp/index.htm', null, 'America/Denver', now()),
  ('Goblin Valley State Park', 'goblin-valley-state-park', 'roadside-oddities', 38.57352, -110.70743, 'Green River', 'UT', 'Thousands of mushroom-shaped sandstone hoodoos fill a basin that looks more like a fabricated alien landscape than a conventional desert valley. The formations are publicly accessible within the state park.', 'open', 'https://stateparks.utah.gov/parks/goblin-valley/', null, 'America/Denver', now()),
  ('Fantasy Canyon', 'fantasy-canyon', 'roadside-oddities', 40.0572, -109.39469, 'Ouray', 'UT', 'Extremely delicate sandstone has eroded into twisted figures, fins and spires in a compact badland east of Vernal. The shapes are so intricate that many have acquired informal creature-like names.', 'open', 'https://www.blm.gov/visit/fantasy-canyon', null, 'America/Denver', now()),
  ('Devil''s Slide', 'devils-slide', 'roadside-oddities', 41.06194, -111.55472, 'Croydon', 'UT', 'Two parallel limestone fins rise from a mountainside with a narrow trough between them, creating the appearance of an enormous natural playground slide. A lawful highway pullout provides the safest view.', 'roadside', 'https://www.roadsideamerica.com/tip/5976', null, 'America/Denver', now()),
  ('Pando, the Trembling Giant', 'pando-the-trembling-giant', 'roadside-oddities', 38.525, -111.75, 'Richfield', 'UT', 'This grove of quaking aspens is genetically one organism connected by a shared root system, making it one of the most massive known living organisms on Earth. Trails and roads in Fishlake National Forest pass through the clone.', 'open', 'https://www.fs.usda.gov/', null, 'America/Denver', now()),
  ('Bonneville Salt Flats', 'bonneville-salt-flats', 'roadside-oddities', 40.76239, -113.89662, 'Wendover', 'UT', 'A vast crust of white salt covers the remnants of ancient Lake Bonneville and has hosted generations of land-speed record attempts. Conditions vary seasonally, and driving on wet salt can damage the surface and strand vehicles.', 'open', 'https://www.blm.gov/visit/bonneville-salt-flats', null, 'America/Denver', now()),
  ('Bonneville Speedway', 'bonneville-speedway', 'weird-history', 40.78534, -113.85214, 'Wendover', 'UT', 'The historic measured-mile courses on the Bonneville Salt Flats became synonymous with experimental cars, motorcycles and world land-speed records. Event access depends on salt conditions and scheduled racing meets.', 'limited', 'https://www.blm.gov/visit/bonneville-salt-flats', null, 'America/Denver', now()),
  ('Homestead Crater', 'homestead-crater', 'roadside-oddities', 40.52359, -111.48513, 'Midway', 'UT', 'A geothermal spring sits inside a 55-foot-tall limestone dome with an opening at the top. Commercially managed access allows swimming, soaking and diving inside the strange mineral formation.', 'limited', 'https://homesteadresort.com/utah-resort-things-to-do/homestead-crater/', null, 'America/Denver', now()),
  ('Mystic Hot Springs', 'mystic-hot-springs', 'roadside-oddities', 38.63841, -112.11085, 'Monroe', 'UT', 'Mineral water is diverted through outdoor bathtubs and pools surrounded by brightly colored travertine deposits. The privately operated site blends a natural spring with deliberately eccentric human additions.', 'limited', 'https://mystichotsprings.com/', null, 'America/Denver', now()),
  ('Upheaval Dome', 'upheaval-dome', 'roadside-oddities', 38.42648, -109.92563, 'Moab', 'UT', 'A circular structure in Canyonlands exposes dramatically tilted rocks, long debated as a salt dome before evidence favored a meteorite impact origin. Trails lead to overlooks above the crater-like formation.', 'open', 'https://www.nps.gov/cany/learn/nature/upheavaldome.htm', null, 'America/Denver', now()),
  ('Balanced Rock', 'balanced-rock-arches', 'roadside-oddities', 38.70128, -109.56558, 'Moab', 'UT', 'A huge sandstone boulder appears precariously balanced on a narrow pedestal beside the Arches scenic road. A short loop trail circles the formation.', 'open', 'https://www.nps.gov/arch/planyourvisit/balanced-rock.htm', null, 'America/Denver', now()),
  ('Landscape Arch', 'landscape-arch', 'roadside-oddities', 38.79113, -109.6069, 'Moab', 'UT', 'One of the world''s longest natural rock spans stretches improbably thin across Devils Garden. Large pieces have fallen in recent decades, emphasizing how temporary the delicate structure is.', 'open', 'https://www.nps.gov/arch/', null, 'America/Denver', now()),
  ('Double Arch', 'double-arch', 'roadside-oddities', 38.68879, -109.5384, 'Moab', 'UT', 'Two giant arches share the same eroded foundation, forming a cathedral-like opening reached by a short trail. Their intersecting geometry makes this one of Arches National Park''s strangest formations.', 'open', 'https://www.nps.gov/arch/', null, 'America/Denver', now()),
  ('Delicate Arch', 'delicate-arch', 'roadside-oddities', 38.74362, -109.49929, 'Moab', 'UT', 'Utah''s most recognizable freestanding arch stands alone on a sandstone fin above a natural bowl. The full trail is exposed and strenuous, while a separate viewpoint offers a lower-intensity option.', 'open', 'https://www.nps.gov/arch/', null, 'America/Denver', now()),
  ('Fiery Furnace', 'fiery-furnace', 'roadside-oddities', 38.74338, -109.56451, 'Moab', 'UT', 'A maze of narrow sandstone fins, slots and dead ends creates a natural labyrinth inside Arches National Park. Entry is regulated because route-finding is difficult and biological soil crust is fragile.', 'limited', 'https://www.nps.gov/arch/planyourvisit/fiery-furnace.htm', null, 'America/Denver', now()),
  ('Thor''s Hammer', 'thors-hammer', 'roadside-oddities', 37.62834, -112.16498, 'Bryce Canyon', 'UT', 'A tall hoodoo capped by a broader block resembles an enormous stone hammer rising from Bryce Canyon''s amphitheater. It is visible from the Navajo Loop area.', 'open', 'https://www.nps.gov/brca/', null, 'America/Denver', now()),
  ('Bryce Natural Bridge', 'bryce-natural-bridge', 'roadside-oddities', 37.63134, -112.16393, 'Bryce Canyon', 'UT', 'Despite its name, this large red-rock opening is technically an arch rather than a bridge because it was carved mainly by weathering instead of a stream. A roadside overlook makes it easy to see.', 'open', 'https://www.nps.gov/brca/', null, 'America/Denver', now()),
  ('Cedar Breaks Amphitheater', 'cedar-breaks-amphitheater', 'roadside-oddities', 37.63639, -112.845, 'Brian Head', 'UT', 'A three-mile-wide amphitheater drops into a maze of fins, spires and hoodoos colored by iron and manganese. High elevation brings long winter closures, so access is seasonal.', 'limited', 'https://www.nps.gov/cebr/', null, 'America/Denver', now()),
  ('Devil''s Garden — Grand Staircase', 'devils-garden-grand-staircase', 'roadside-oddities', 37.58534, -111.41487, 'Escalante', 'UT', 'Freestanding hoodoos, arches and balanced forms rise from a small desert garden off Hole-in-the-Rock Road. The short wandering route makes the area unusually accessible for such bizarre erosion.', 'open', 'https://www.blm.gov/visit/devils-garden-outstanding-natural-area', null, 'America/Denver', now()),
  ('Grosvenor Arch', 'grosvenor-arch', 'roadside-oddities', 37.45294, -111.8234, 'Cannonville', 'UT', 'A massive double arch of pale sandstone rises at the end of a paved spur road in Grand Staircase-Escalante. Its paired openings and isolated setting give it a monumental, almost constructed appearance.', 'open', 'https://www.blm.gov/visit/grand-staircase-escalante-national-monument', null, 'America/Denver', now()),
  ('Toadstool Hoodoos', 'toadstool-hoodoos', 'roadside-oddities', 37.1013, -111.87471, 'Big Water', 'UT', 'White and red mushroom-shaped hoodoos stand above a short desert wash, including formations capped by darker boulders. A signed trailhead off U.S. 89 gives straightforward public access.', 'open', 'https://www.blm.gov/visit/grand-staircase-escalante-national-monument', null, 'America/Denver', now()),
  ('Wahweap Hoodoos', 'wahweap-hoodoos', 'roadside-oddities', 37.23857, -111.68396, 'Big Water', 'UT', 'Tall pale pinnacles capped with darker stone have been nicknamed the White Ghosts. The remote hike is exposed and should only be attempted with desert-weather awareness and adequate water.', 'limited', 'https://www.visitutah.com/', null, 'America/Denver', now()),
  ('Belly of the Dragon', 'belly-of-the-dragon', 'roadside-oddities', 37.2116, -112.68214, 'Mount Carmel Junction', 'UT', 'An old drainage tunnel under Highway 89 has eroded into rippled sandstone walls, creating a passage that looks organic and cave-like despite being man-made. Flash-flood conditions can make the tunnel dangerous.', 'open', 'https://www.roadsideamerica.com/tip/57250', null, 'America/Denver', now()),
  ('Little Wild Horse Canyon', 'little-wild-horse-canyon', 'roadside-oddities', 38.58314, -110.8034, 'Green River', 'UT', 'A popular slot canyon near Goblin Valley narrows into twisting sandstone corridors only a few feet wide. Flash floods are the primary hazard, so forecasts must be checked before entering.', 'open', 'https://www.blm.gov/visit/little-wild-horse-canyon', null, 'America/Denver', now()),
  ('The Wedge — Little Grand Canyon', 'the-wedge-little-grand-canyon', 'roadside-oddities', 39.08365, -110.75888, 'Castle Dale', 'UT', 'An overlook on the San Rafael Swell reveals the San Rafael River winding through a deep canyon system often nicknamed Utah''s Little Grand Canyon. Public BLM roads reach the rim.', 'open', 'https://www.blm.gov/visit/wedge-overlook', null, 'America/Denver', now()),
  ('Mexican Hat Rock', 'mexican-hat-rock', 'roadside-oddities', 37.1716, -109.84895, 'Mexican Hat', 'UT', 'A broad flat sandstone cap appears to balance on a much narrower pedestal above the San Juan River valley. The formation is visible from public roads and nearby BLM land.', 'roadside', 'https://www.blm.gov/visit/mexican-hat', null, 'America/Denver', now()),
  ('Goosenecks State Park', 'goosenecks-state-park', 'roadside-oddities', 37.17403, -109.92767, 'Mexican Hat', 'UT', 'The San Juan River doubles back through a series of tightly entrenched meanders more than a thousand feet below the rim. The geometry is best understood from the developed state-park overlook.', 'open', 'https://stateparks.utah.gov/parks/goosenecks/', null, 'America/Denver', now()),
  ('Valley of the Gods', 'valley-of-the-gods', 'roadside-oddities', 37.26451, -109.8835, 'Mexican Hat', 'UT', 'A dirt-road loop winds among isolated sandstone towers, buttes and pinnacles that resemble a miniature Monument Valley. Road conditions can become poor after storms.', 'open', 'https://www.blm.gov/visit/valley-gods', null, 'America/Denver', now()),
  ('Sipapu Natural Bridge', 'sipapu-natural-bridge', 'roadside-oddities', 37.61542, -110.00384, 'Lake Powell', 'UT', 'One of the world''s largest natural bridges spans a canyon in Natural Bridges National Monument. A steep trail descends to its base while viewpoints offer easier access.', 'open', 'https://www.nps.gov/nabr/', null, 'America/Denver', now()),
  ('Kachina Natural Bridge', 'kachina-natural-bridge', 'roadside-oddities', 37.59191, -110.00947, 'Lake Powell', 'UT', 'This thick, relatively young natural bridge rises above White Canyon and bears nearby rock art and archaeological evidence. A strenuous trail reaches the span.', 'open', 'https://www.nps.gov/nabr/', null, 'America/Denver', now()),
  ('Owachomo Natural Bridge', 'owachomo-natural-bridge', 'roadside-oddities', 37.57085, -110.01266, 'Lake Powell', 'UT', 'The thinnest and oldest-looking of the monument''s three major bridges appears almost impossibly delicate compared with the canyon walls around it. A short trail reaches its base.', 'open', 'https://www.nps.gov/nabr/', null, 'America/Denver', now()),
  ('Spiral Jetty', 'spiral-jetty', 'roadside-oddities', 41.43774, -112.6683, 'Rozel Point', 'UT', 'Robert Smithson''s 1970 earthwork coils more than 1,500 feet into the Great Salt Lake from black basalt shoreline. Water level changes can leave the spiral submerged, exposed or surrounded by pinkish salt water.', 'open', 'https://www.diaart.org/visit/visit-our-locations-sites/robert-smithson-spiral-jetty', null, 'America/Denver', now()),
  ('Sun Tunnels', 'sun-tunnels', 'roadside-oddities', 41.30358, -113.86373, 'Lucin', 'UT', 'Nancy Holt''s four giant concrete cylinders frame the rising and setting sun around the solstices, while smaller holes map constellations onto the tunnel interiors. The remote desert site requires careful travel planning.', 'open', 'https://umfa.utah.edu/land-art/sun-tunnels', null, 'America/Denver', now()),
  ('Metaphor: The Tree of Utah', 'metaphor-the-tree-of-utah', 'roadside-oddities', 40.72917, -113.45972, 'Wendover', 'UT', 'Karl Momen''s 87-foot concrete tree rises improbably from the Bonneville Salt Flats beside Interstate 80. There is no legal stopping area at the sculpture, so it should only be viewed while passing.', 'roadside', 'https://www.roadsideamerica.com/story/2230', null, 'America/Denver', now()),
  ('Out of the Blue — 9th & 9th Whale', 'out-of-the-blue-9th-9th-whale', 'roadside-oddities', 40.74937, -111.86504, 'Salt Lake City', 'UT', 'A full-size humpback whale appears to breach from a traffic circle in a landlocked neighborhood. Salt Lake City formally embraces the sculpture as a local public-art landmark.', 'open', 'https://www.slc.gov/mayor/2026/08/03/salt-lake-city-unveils-new-mural-for-out-of-the-blue-iconic-9th-9th-whale/', null, 'America/Denver', now()),
  ('Gilgal Sculpture Garden', 'gilgal-sculpture-garden', 'roadside-oddities', 40.75872, -111.86811, 'Salt Lake City', 'UT', 'This hidden city park contains a Joseph Smith sphinx, brick-clothed self-portrait, giant carved books and dozens of inscribed stones created by stonemason Thomas Child. Salt Lake City calls it Utah''s only identified visionary art environment.', 'open', 'https://www.slc.gov/parks/parks-division/gilgal-garden/', null, 'America/Denver', now()),
  ('Hollow Mountain Gas Station', 'hollow-mountain-gas-station', 'roadside-oddities', 38.3733, -110.7159, 'Hanksville', 'UT', 'A convenience store and gas station is built directly into a hollowed sandstone outcrop, so shelves and coolers sit against raw rock walls. It remains an operating roadside business.', 'open', 'https://www.roadsideamerica.com/tip/12479', null, 'America/Denver', now()),
  ('Hole N'' the Rock', 'hole-n-the-rock', 'roadside-oddities', 38.44328, -109.4268, 'Moab', 'UT', 'A 5,000-square-foot home was carved into a sandstone cliff beginning in the mid-twentieth century and is now toured as a preserved roadside attraction. The site also contains eclectic sculptures and displays.', 'limited', 'https://www.theholentherock.com/', null, 'America/Denver', now()),
  ('Moqui Cave', 'moqui-cave', 'museums', 37.11464, -112.55518, 'Kanab', 'UT', 'A roadside sandstone cave houses a family-run collection of fossils, minerals, Native American artifacts and pioneer objects. The cave itself began as a 1950s bar and dance hall.', 'limited', 'https://www.moquicave.com/', null, 'America/Denver', now()),
  ('Little Hollywood Movie Museum', 'little-hollywood-movie-museum', 'weird-history', 37.04784, -112.52668, 'Kanab', 'UT', 'Kanab''s long career as a western-film location is preserved through surviving sets, props and reconstructed facades. The attraction ties a real desert town to decades of manufactured Old West scenery.', 'limited', 'https://www.littlehollywoodmuseum.org/', null, 'America/Denver', now()),
  ('Moab Museum of Film and Western Heritage', 'moab-museum-of-film-and-western-heritage', 'weird-history', 38.4813, -109.3575, 'Moab', 'UT', 'Located at Red Cliffs Lodge, this small museum preserves photographs, props and stories from westerns and other movies filmed across the Moab landscape. The setting connects Hollywood mythology directly to real shooting locations.', 'limited', 'https://www.redcliffslodge.com/moab-museum/', null, 'America/Denver', now()),
  ('Moab Giants', 'moab-giants', 'roadside-oddities', 38.63799, -109.68087, 'Moab', 'UT', 'More than a hundred life-size dinosaur models line an outdoor trail near fossil-bearing landscapes, while indoor exhibits cover tracks and paleontology. It is intentionally theatrical but grounded in Utah dinosaur science.', 'limited', 'https://moabgiants.com/', null, 'America/Denver', now()),
  ('Dinosaur National Monument Quarry Exhibit Hall', 'dinosaur-national-monument-quarry-exhibit-hall', 'museums', 40.44072, -109.30054, 'Jensen', 'UT', 'A cliff face inside the exhibit hall contains roughly 1,500 dinosaur bones still embedded where they were found. Visitors can see and in some places touch genuine Jurassic fossils.', 'limited', 'https://www.nps.gov/dino/planyourvisit/quarry-exhibit-hall.htm', null, 'America/Denver', now()),
  ('Utah Field House Dinosaur Garden', 'utah-field-house-dinosaur-garden', 'roadside-oddities', 40.45551, -109.52879, 'Vernal', 'UT', 'Full-size dinosaur replicas surround the state museum, including a towering Tyrannosaurus and Stegosaurus. Inside, fossils and a working laboratory connect the outdoor roadside spectacle to regional paleontology.', 'limited', 'https://stateparks.utah.gov/parks/utah-field-house/', null, 'America/Denver', now()),
  ('George S. Eccles Dinosaur Park', 'george-s-eccles-dinosaur-park', 'roadside-oddities', 41.23525, -111.93122, 'Ogden', 'UT', 'More than 100 life-size prehistoric models occupy an outdoor park with sound effects and vegetation, creating a deliberately immersive dinosaur landscape. An indoor museum adds fossils and paleontology exhibits.', 'limited', 'https://www.dinosaurpark.org/', null, 'America/Denver', now()),
  ('St. George Dinosaur Discovery Site', 'st-george-dinosaur-discovery-site', 'museums', 37.10147, -113.55613, 'St. George', 'UT', 'A museum building protects dinosaur tracks exactly where they were discovered on the former Johnson farm. Thousands of footprints and trace fossils preserve an unusually detailed Early Jurassic ecosystem.', 'limited', 'https://utahdinosaurs.org/', null, 'America/Denver', now()),
  ('Copper Ridge Dinosaur Trackways', 'copper-ridge-dinosaur-trackways', 'museums', 38.74661, -109.66852, 'Moab', 'UT', 'A short BLM trail reaches large sauropod and theropod footprints preserved in sandstone north of Moab. The tracks remain in place in the rock rather than behind museum glass.', 'open', 'https://www.visitutah.com/things-to-do/history-culture/dinosaurs-paleontology', null, 'America/Denver', now()),
  ('Mill Canyon Dinosaur Tracksite', 'mill-canyon-dinosaur-tracksite', 'museums', 38.72012, -109.69514, 'Moab', 'UT', 'A boardwalk crosses a dense tracksite preserving footprints from multiple dinosaur species. The BLM-managed site lets visitors examine an actual ancient walking surface without stepping directly on the fossils.', 'open', 'https://www.blm.gov/visit/mill-canyon-dinosaur-tracksite', null, 'America/Denver', now()),
  ('Poison Spider Dinosaur Tracksite', 'poison-spider-dinosaur-tracksite', 'museums', 38.53291, -109.60869, 'Moab', 'UT', 'Tracks and rock art occur near the same Colorado River trailhead used for Longbow Arch. The pairing of dinosaur traces and later human markings makes the site especially strong for OddWay.', 'open', 'https://www.blm.gov/visit/longbow-arch-trailhead', null, 'America/Denver', now()),
  ('Jurassic National Monument — Cleveland-Lloyd Dinosaur Quarry', 'jurassic-national-monument-cleveland-lloyd-dinosaur-quarry', 'museums', 39.32198, -110.68572, 'Elmo', 'UT', 'This fossil quarry contains an unusually dense concentration of Jurassic dinosaur bones, including many Allosaurus remains. Scientists still debate why so many animals accumulated here.', 'limited', 'https://www.blm.gov/visit/jurassic-national-monument', null, 'America/Denver', now()),
  ('Natural History Museum of Utah — Past Worlds', 'natural-history-museum-of-utah-past-worlds', 'museums', 40.7642, -111.82205, 'Salt Lake City', 'UT', 'The museum''s paleontology halls display Utah dinosaurs, fossils and changing discoveries from one of North America''s richest fossil states. The dramatic building sits directly against fossil-bearing regional geology.', 'limited', 'https://nhmu.utah.edu/', null, 'America/Denver', now()),
  ('USU Eastern Prehistoric Museum', 'usu-eastern-prehistoric-museum', 'museums', 39.59908, -110.81063, 'Price', 'UT', 'This university museum combines major dinosaur collections with archaeology from the Fremont and other Indigenous cultures of eastern Utah. Its concentration of locally excavated material gives it stronger OddWay relevance than a generic natural-history museum.', 'limited', 'https://eastern.usu.edu/museum/', null, 'America/Denver', now()),
  ('Dinosaur Museum of Blanding', 'dinosaur-museum-of-blanding', 'museums', 37.62387, -109.47811, 'Blanding', 'UT', 'The privately operated museum is known for dinosaur eggs, fossil skin, skeletons and displays about dinosaurs in movies and popular culture. Its mix of serious specimens and cinematic history is unusually specific.', 'limited', 'https://www.dinosaur-museum.org/', null, 'America/Denver', now()),
  ('Hill Aerospace Museum', 'hill-aerospace-museum', 'weird-history', 41.16252, -112.01987, 'Hill AFB', 'UT', 'Dozens of military aircraft, missiles and aerospace artifacts fill a large museum just outside the active Air Force base. Public access is separate from restricted base areas.', 'open', 'https://www.aerospaceutah.org/', null, 'America/Denver', now()),
  ('Historic Wendover Airfield', 'historic-wendover-airfield', 'weird-history', 40.71844, -114.03536, 'Wendover', 'UT', 'This preserved World War II air base trained bomber crews and played a direct role in the Manhattan Project. Museums, hangars and the atomic-bomb loading pit survive at one of the country''s most intact wartime airfields.', 'limited', 'https://wendoverairfield.org/visit/', null, 'America/Denver', now()),
  ('ATK / Northrop Grumman Rocket Garden', 'atk-northrop-grumman-rocket-garden', 'weird-history', 41.62988, -112.16162, 'Corinne', 'UT', 'Full-scale rocket motors and space-shuttle booster hardware stand outdoors near the northern Utah plant that built major solid-fuel rocket systems. The display can be viewed from the designated visitor area when open.', 'roadside', 'https://www.roadsideamerica.com/tip/1703', null, 'America/Denver', now()),
  ('Clark Planetarium', 'clark-planetarium', 'museums', 40.76718, -111.90315, 'Salt Lake City', 'UT', 'Interactive exhibits include meteorites, planetary displays and space-science installations in downtown Salt Lake City. The real extraterrestrial material and large-format astronomy programming make it a useful science-side OddWay stop.', 'open', 'https://slco.org/clark-planetarium/', null, 'America/Denver', now()),
  ('John Hutchings Museum of Natural History', 'john-hutchings-museum-of-natural-history', 'museums', 40.38708, -111.84953, 'Lehi', 'UT', 'This old-style local museum mixes fossils, taxidermy, pioneer objects, Native American material, minerals and unusual historical specimens under one roof. Its deliberately eclectic collection feels closer to a cabinet of curiosities than a conventional single-topic museum.', 'limited', 'https://johnhutchingsmuseum.org/', null, 'America/Denver', now()),
  ('Pioneer Memorial Museum', 'pioneer-memorial-museum', 'museums', 40.77787, -111.888, 'Salt Lake City', 'UT', 'Six floors of artifacts collected by the Daughters of Utah Pioneers create an enormous, densely packed archive of nineteenth-century Utah life. The volume and eccentric variety of objects make it far stranger than a normal regional-history display.', 'limited', 'https://isdup.org/pioneer-memorial-museum/', null, 'America/Denver', now()),
  ('Rat Fink Museum', 'rat-fink-museum', 'roadside-oddities', 39.26883, -111.63644, 'Manti', 'UT', 'A small museum celebrates Ed ''Big Daddy'' Roth, creator of the grotesque hot-rod mascot Rat Fink, in the Utah town where he spent his later years. Memorabilia connects custom-car culture, monster art and underground illustration.', 'limited', 'https://www.roadsideamerica.com/tip/7241', null, 'America/Denver', now()),
  ('Big John — Coal Miner Muffler Man', 'big-john-coal-miner-muffler-man', 'roadside-oddities', 39.68484, -110.85479, 'Helper', 'UT', 'A giant fiberglass Muffler Man repainted as a black-clad coal miner stands along Helper''s main street, reflecting the town''s mining identity through classic roadside-advertising sculpture.', 'roadside', 'https://www.roadsideamerica.com/tip/1710', null, 'America/Denver', now()),
  ('World''s Second-Largest Watermelon Slice', 'worlds-second-largest-watermelon-slice', 'roadside-oddities', 38.99343, -110.15208, 'Green River', 'UT', 'A giant painted watermelon slice pays tribute to Green River''s long association with melon farming and the annual Melon Days celebration. It is a straightforward roadside photo stop.', 'roadside', 'https://www.roadsideamerica.com/tip/2087', null, 'America/Denver', now()),
  ('Carl''s Critter Garden', 'carls-critter-garden', 'roadside-oddities', 38.37368, -110.7146, 'Hanksville', 'UT', 'Scrap metal, machine parts and discarded tools are welded into dinosaurs, animals and odd creatures beside the highway. The informal outdoor collection functions as a constantly evolving desert folk-art garden.', 'open', 'https://www.roadsideamerica.com/tip/41817', null, 'America/Denver', now()),
  ('Philo T. Farnsworth Birthplace Marker', 'philo-t-farnsworth-birthplace-marker', 'weird-history', 38.27691, -112.64105, 'Beaver', 'UT', 'A marker and local interpretation commemorate television pioneer Philo Farnsworth, who was born near Beaver and conceived important electronic-television ideas while still young. It gives OddWay a concrete stop tied to an invention that changed modern life.', 'roadside', 'https://www.roadsideamerica.com/tip/7158', null, 'America/Denver', now())
on conflict (slug) do update set
  description   = excluded.description,
  public_access = excluded.public_access,
  source        = excluded.source,
  website       = excluded.website,
  verified_at   = excluded.verified_at;

select count(*) as utah from public.stops where state = 'UT';
